from cloud_common import *  # noqa: F401,F403
R = 'f7-cloud'
T = []

# ---------------------------------------------------------------- 589 kubernetes scheduling
T.append(topic(589, 'kubernetes-scheduling-placement', R, 13, 'Kubernetes Scheduling: Placement, Taints and Topology Spread',
 ['Explain how the scheduler filters and scores nodes using requests, not live usage',
  'Steer pods onto or away from nodes with selectors, affinity, taints and tolerations',
  'Spread replicas across zones with topology spread constraints, and predict preemption'],
 3, 13, [322],
 [text(589, 1, 'Filter, then score',
   'For each pending pod the scheduler first filters out nodes that cannot run it: not enough unreserved CPU or memory for its requests, a taint it does not tolerate, a node selector or affinity rule it fails, a volume in another zone. It then scores the nodes that remain, for example preferring spread or less-loaded nodes, and binds the pod to the best one. Requests are what count, not current usage: a node at 20% CPU can still be full if its pods have reserved all of it.',
   ['scheduling-filter-score']),
  text(589, 2, 'Attract and repel: affinity, taints and tolerations',
   'A node selector or node affinity pulls a pod towards nodes with certain labels, such as a GPU type or a zone. A taint on a node pushes pods away: only pods with a matching toleration may land there. They solve different halves of the problem. To reserve GPU nodes for GPU jobs, taint the GPU nodes so other pods stay off, and give GPU jobs both the toleration and an affinity so they actually go there. A toleration alone only permits a node; it does not choose it.',
   ['node-placement']),
  diagram(589, 3, 'How one pod is placed', 'The scheduler only ever reasons about declared requests and rules.', ['scheduling-filter-score', 'topology-spread'],
   ['A pod is created with requests, tolerations and spread rules',
    'Filter: drop nodes without enough unreserved requests',
    'Filter: drop tainted nodes the pod does not tolerate, and nodes failing affinity',
    'Filter: drop nodes that would break a hard topology spread rule',
    'Score the rest, for example preferring balance across zones',
    'Bind the pod to the best node; the kubelet starts it']),
  text(589, 4, 'Worked example: nine replicas, three zones',
   'A Deployment of 9 replicas has a topology spread constraint on the zone label with a maximum skew of 1, so no zone may have more than one pod above another: 3, 3, 3. If zone C fails, its 3 pods are recreated; with the rule set to schedule anyway, they land in A and B, giving 5 and 4. Each node has 7.5 vCPU allocatable and each pod requests 1 vCPU, so a node fits 7 pods, and the remaining zones need enough spare requests for the extra pods, or the replacements stay Pending.',
   ['topology-spread']),
  text(589, 5, 'Trap: Pending pods on idle-looking nodes',
   'Dashboards show nodes at 20% CPU while new pods stay Pending with “insufficient cpu”. The pods already on those nodes request far more than they use, so the scheduler sees the nodes as full. Fix requests from measured usage, and let a cluster autoscaler add nodes when pods are Pending. Adding a CPU limit does not help, because the scheduler places pods by requests, not limits.',
   ['scheduling-filter-score']),
  text(589, 6, 'When the cluster is full: priority and preemption',
   'Pods can carry a priority class. When a high-priority pod cannot fit anywhere, the scheduler may preempt: it evicts lower-priority pods from a node to make room, trying to respect their disruption budgets, though it cannot promise to. This keeps critical workloads running during a squeeze, but a careless high default priority lets ordinary deploys evict each other.',
   ['priority-preemption'])],
 [mc('t589-a1', 'scheduling-filter-score', 'New pods stay Pending with “0/6 nodes available: insufficient cpu”, yet every node shows about 20% CPU in use. What is the most likely cause?',
   [('a', 'The metrics pipeline is down, so the scheduler cannot see the real usage'),
    ('b', 'Existing pods request much more CPU than they use'),
    ('c', 'The CPU limits on the new pods are set lower than their requests'),
    ('d', 'The nodes need a restart before they accept new pods')], 'b',
   'The scheduler adds up requests, not usage, so over-sized requests make idle nodes look full. It never reads live metrics for placement, a limit below a request is rejected when the pod is created rather than leaving it Pending, and restarting nodes frees no requests.'),
  mc('t589-a2', 'node-placement', 'Expensive GPU nodes keep filling up with ordinary web pods. What keeps them for GPU jobs?',
   [('a', 'Add a node selector for the GPU label to the GPU jobs only'),
    ('b', 'Taint the GPU nodes, and give GPU jobs a toleration and affinity'),
    ('c', 'Give the GPU jobs a higher priority class than the web pods'),
    ('d', 'Move the GPU jobs into a namespace of their own')], 'b',
   'Only a taint repels other pods; the toleration lets GPU jobs in and affinity sends them there. A selector on GPU jobs does not stop web pods landing on GPU nodes, priority only matters when the cluster is full, and namespaces do not control which nodes pods run on.'),
  mc('t589-a3', 'topology-spread', 'All 6 replicas of a service ended up in one zone, and a zone outage took it down. What fix targets the cause?',
   [('a', 'Pod anti-affinity on the hostname label so no two replicas share a node'),
    ('b', 'A disruption budget that keeps at least 4 replicas running'),
    ('c', 'A topology spread constraint on the zone label with a skew of 1'),
    ('d', 'Raising the replica count to 12 so more of them survive')], 'c',
   'Spreading on the zone label keeps replicas balanced across zones. Hostname anti-affinity spreads across nodes that may all sit in one zone, a disruption budget only limits voluntary evictions, and 12 replicas can still all land in the same zone.'),
  mc('t589-a4', 'priority-preemption', 'The cluster is full and a pod with a high priority class is Pending. What does the scheduler try?',
   [('a', 'Evicting lower-priority pods on a node so that the new pod fits'),
    ('b', 'Throttling the CPU of other pods until the new pod’s request fits'),
    ('c', 'Holding the pod until another pod on some node exits by itself'),
    ('d', 'Placing the pod anyway and letting the node overcommit its memory')], 'a',
   'That is preemption: lower-priority pods are evicted, with their disruption budgets respected where possible. Throttling and overcommit do not create schedulable requests, and waiting is what happens to pods without enough priority to preempt.'),
  est('t589-a5', 'scheduling-filter-score', 'A node has 7.5 vCPU and 30 GiB of allocatable capacity. Each pod requests 1 vCPU and 2 GiB of memory. How many of these pods fit on the node?', 'pods', 7,
   ['Nothing else runs on the node', 'Only requests count for placement'], 'min(7.5 ÷ 1, 30 ÷ 2), rounded down', 'CPU allows 7 pods, memory allows 15, so 7 pods',
   'Sanity check: CPU is the binding resource here, so half the node’s memory sits unrequested; a pod shape that requests 0.5 vCPU and 4 GiB would pack this node better.', 0.05, [15, 8]),
  tradeoff('t589-a6', 'topology-spread', 'A payments API runs 9 replicas in a three-zone cluster and must survive a zone loss.',
   ['Each zone has room for only 2 extra pods', 'Losing a zone must not drop below 6 replicas', 'Deploys must not stall on spread rules'],
   [('p1', 'Zone spread with skew 1, scheduling anyway if the rule cannot be met, plus spare capacity per zone', 'Soft spread with headroom'),
    ('p2', 'Zone spread with skew 1 that refuses to schedule if the rule cannot be met', 'Hard spread'),
    ('p3', 'No spread rule; rely on the scheduler’s default scoring', 'Default scoring')], 'p1',
   [('r1', 'Replicas start balanced, so a zone loss removes only about a third'), ('r3', 'A hard rule is always safer because it never allows imbalance'),
    ('r2', 'Replacements still schedule into the surviving zones after a loss'), ('r4', 'Default scoring spreads replicas across zones reliably on its own')],
   ['r1', 'r2'], ['r3', 'r4'],
   {'r3': 'After a zone loss a hard rule can leave replacements Pending, because two zones cannot stay within a skew of 1 of a zone with no capacity.',
    'r4': 'Default scoring only prefers spread; under pressure it can still pack replicas into one zone.'},
   'Balance replicas with a zone spread rule, but let it bend after a failure and keep headroom so the surviving zones can absorb the replacements.')],
 flash(589, [('What does the scheduler count?', 'Requests, not live usage; a busy-looking or idle-looking node is irrelevant.'),
             ('Taint vs affinity?', 'A taint repels pods without a toleration; affinity attracts pods to labelled nodes. Use both to dedicate nodes.'),
             ('Topology spread maxSkew 1?', 'No topology domain, such as a zone, may hold more than one matching pod above another.')]),
 src([('Kubernetes: Kubernetes Scheduler', 'https://kubernetes.io/docs/concepts/scheduling-eviction/kube-scheduler/'),
      ('Kubernetes: Taints and Tolerations', 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/'),
      ('Kubernetes: Pod Topology Spread Constraints', 'https://kubernetes.io/docs/concepts/scheduling-eviction/topology-spread-constraints/'),
      ('Kubernetes: Pod Priority and Preemption', 'https://kubernetes.io/docs/concepts/scheduling-eviction/pod-priority-preemption/')]),
 deep(['scheduling-filter-score', 'node-placement', 'topology-spread', 'priority-preemption'], 'How the scheduler decides where a pod runs',
  ['The scheduler watches for pods with no node assigned. For each one it runs a filtering phase that removes every node where the pod cannot run, then a scoring phase that ranks the rest, and finally binds the pod to the highest-scoring node. If no node passes filtering, the pod stays Pending and an event explains which filter failed on how many nodes, which is the first thing to read when debugging.',
   'Resource filtering compares the pod’s requests with each node’s allocatable capacity minus the requests of pods already bound there. Allocatable is less than the machine size because the operating system, the kubelet and system daemons reserve some. Live usage is not considered, so over-requesting wastes capacity and under-requesting packs nodes until pods contend or are evicted. Requests should come from measured usage at a high percentile.',
   'Placement rules come in two directions. Node selectors and node affinity attract a pod to nodes with labels, as hard requirements or soft preferences. Taints repel: a tainted node accepts only pods that tolerate the taint, which is how dedicated node pools, GPU nodes and control-plane nodes are kept clear. Pod affinity and anti-affinity place pods relative to other pods, for example keeping a cache next to its clients or two replicas off the same node.',
   'Topology spread constraints balance matching pods across a topology key such as the zone or hostname label. maxSkew bounds the difference between the fullest and emptiest domain. The whenUnsatisfiable setting chooses between refusing to schedule, which keeps balance strict but can leave pods Pending after a failure, and scheduling anyway while preferring balance. Spread across zones is what turns a multi-zone cluster into multi-zone resilience for a given service.',
   'When nothing fits, two mechanisms act. A cluster autoscaler sees Pending pods and adds nodes from a node group that would fit them. Priority and preemption let a higher-priority pod evict lower-priority ones from a node so it can run, which keeps critical system and production pods alive during a squeeze. Preemption tries to respect disruption budgets but cannot guarantee it, so priority classes should be few and deliberate.'],
  ['Clusters shared by several teams or workload types, where placement must be predictable.', 'Services that must survive a zone or node loss, and expensive node types that must stay dedicated.'],
  ['Avoid hard affinity and spread rules that can leave pods Pending when capacity is tight.', 'Avoid many priority classes or a high default priority; deploys then preempt each other.'],
  ['Tool', 'Does', 'Watch out for'],
  [['Node affinity or selector', 'Attracts pods to labelled nodes', 'Does not keep other pods off'],
   ['Taint and toleration', 'Repels pods without a toleration', 'A toleration alone does not attract'],
   ['Topology spread', 'Balances pods across zones or nodes', 'Hard rules can block rescheduling'],
   ['Priority class', 'Lets important pods preempt', 'Wrong defaults cause eviction churn']],
  'Packing a node and surviving a zone',
  ['Node allocatable: 7.5 vCPU, 30 GiB', 'Pod requests: 1 vCPU, 2 GiB', '9 replicas over 3 zones, 1 node per zone, illustrative'],
  ['Per node: CPU fits 7, memory fits 15, so 7 pods; CPU is the binding resource.',
   'Spread 3, 3, 3 uses 3 of 7 slots per node, leaving 4 spare per zone.',
   'Zone C lost: 3 replacements land in A and B as 5 and 4, using 9 of their 14 slots, so they fit.'],
  'Requests set how many pods fit; spread and spare slots per zone decide whether a zone loss is absorbed or leaves pods Pending.',
  'Scheduling rules in the Kubernetes docs', 'Official documentation',
  'The Kubernetes documentation describes scheduling as filtering then scoring, and documents taints and tolerations, node affinity, inter-pod affinity, topology spread constraints and priority with preemption as the main placement controls. It notes that preemption tries to respect disruption budgets but cannot guarantee it, and that topology spread can either refuse to schedule or schedule anyway when the skew cannot be met.',
  [('“The node is at 20% CPU, so the pod should fit.”', '“I’d compare requests with allocatable; the scheduler only counts what pods reserve.”'),
   ('“We added a toleration, so GPU jobs will run on GPU nodes.”', '“I’d add node affinity too, because a toleration only allows a node, it does not pick it.”')],
  ['The scheduler filters and scores nodes on requests, not live usage.', 'Taints keep pods off; affinity draws pods on; dedicate nodes with both.', 'Spread replicas across zones and keep spare requests per zone for a loss.', 'Priority lets critical pods preempt; keep classes few and deliberate.']),
 predict('Dedicated nodes that are not dedicated',
  'You add a toleration for the gpu=true taint to your training jobs, but you do not taint any nodes and add no affinity. A week later the training jobs are running on ordinary nodes and web pods are on the GPU nodes.',
  [('a', 'Expected: without a taint nothing is repelled, and without affinity nothing is attracted',
    'Right: a toleration only matters on a tainted node, and nothing told the jobs where to go.'),
   ('b', 'A bug: a toleration should pull the jobs onto the GPU nodes',
    'Tolerations permit; they do not attract. That is the job of node affinity or a selector.'),
   ('c', 'The scheduler ignores tolerations unless the pods also have a high priority',
    'Priority is unrelated to tolerations; it only matters when the cluster is full.')], 'a',
  'Taint the GPU nodes so other pods stay off, and give the training jobs both the toleration and a node affinity for the GPU label.'),
 see([(322, 'Requests, limits and probes, the inputs the scheduler works from'), (581, 'Why spreading across zones only helps if each zone has spare capacity'), (328, 'Autoscaling that adds nodes when pods are Pending')])))

# ---------------------------------------------------------------- 590 kubernetes networking
T.append(topic(590, 'kubernetes-services-ingress-network-policy', R, 14, 'Kubernetes Networking: Services, Gateways and Network Policies',
 ['Explain how a Service gives pods a stable name and virtual IP, and why it balances connections rather than requests',
  'Choose between LoadBalancer Services and a shared Ingress or Gateway for outside traffic',
  'Write network policies that default-deny without breaking DNS'],
 3, 14, [322, 329],
 [text(590, 1, 'Services: a stable name in front of moving pods',
   'Pods come and go with new addresses, so clients never call pods directly. A Service selects pods by label and gets a stable virtual IP and a DNS name such as orders.shop.svc.cluster.local. The cluster keeps a list of the ready pods behind it, its endpoints, and the node networking layer forwards each new connection to the virtual IP to one of them. Only ready pods are listed, which is how readiness probes take a pod out of rotation.',
   ['service-virtual-ip']),
  text(590, 2, 'Misconception: a Service balances every request',
   'The virtual IP is balanced per connection, not per request. HTTP/1.1 keep-alive and especially HTTP/2 or gRPC reuse one connection for thousands of requests, so a few clients holding long-lived connections can pin all their traffic to a few pods while the rest sit idle. Fixes are client-side balancing over the endpoint list, a proxy or mesh that balances per request, or limiting connection lifetime so connections are rebalanced.',
   ['service-virtual-ip']),
  diagram(590, 3, 'From the internet to a pod', 'One shared entry point routes by host and path, then Services pick pods.', ['ingress-gateway', 'service-virtual-ip'],
   ['The client resolves shop.example.com to the cloud load balancer',
    'The load balancer forwards to the gateway or ingress controller pods',
    'The gateway terminates TLS and matches the host and path rules',
    'The matching route names a backend Service',
    'The Service’s endpoints list only ready pods',
    'The connection reaches one ready pod']),
  text(590, 4, 'Getting traffic in: LoadBalancer, Ingress and Gateway',
   'A Service of type LoadBalancer asks the cloud for a load balancer per Service, which is simple but costs one load balancer and one address for each. Ingress and its successor, the Gateway API, put one shared layer 7 entry point in front of many Services, routing by hostname and path and terminating TLS in one place. The Gateway API splits the roles: the platform team owns the Gateway and its listeners, and app teams attach their own HTTP routes to it.',
   ['ingress-gateway']),
  text(590, 5, 'Network policies: default allow until you say otherwise',
   'By default every pod can reach every other pod. A network policy selects pods and lists the traffic allowed in or out; once any policy selects a pod for a direction, everything not allowed in that direction is dropped. Policies only work if the cluster’s network plugin enforces them. A common baseline is a default-deny policy per namespace, then small policies that allow, say, frontend to api on port 8080.',
   ['network-policy']),
  text(590, 6, 'Trap: default-deny egress breaks DNS',
   'A team adds a default-deny egress policy and every service starts failing with name-resolution errors, not connection errors. The pods can no longer reach the cluster DNS service, so no name resolves at all. Any egress policy needs an explicit allow to the DNS pods on port 53 over both UDP and TCP, alongside the destinations each workload really needs.',
   ['network-policy', 'cluster-dns'])],
 [mc('t590-a1', 'service-virtual-ip', 'What does a ClusterIP Service give the clients inside the cluster?',
   [('a', 'An address that is reachable from the public internet'),
    ('b', 'A stable virtual IP and DNS name for ready pods'),
    ('c', 'A proxy that retries a failed request on another pod'),
    ('d', 'A single pod chosen to handle all of the service’s traffic')], 'b',
   'A ClusterIP is internal and stable, and forwards connections to ready pods behind it. It is not public, and it does not retry requests or pin traffic to one pod; retries per request need a client library, a proxy or a mesh.'),
  mc('t590-a2', 'network-policy', 'A policy allows ingress to the api pods only from pods labelled app=frontend. What happens to a request from a batch pod to api?',
   [('a', 'It is allowed, because policies only log traffic they do not list'),
    ('b', 'It is allowed, because batch runs in the same namespace as api'),
    ('c', 'It is dropped, along with traffic from the frontend pods'),
    ('d', 'It is dropped, because api now only accepts traffic from frontend')], 'd',
   'Once a policy selects the api pods for ingress, only listed sources get in, so batch is dropped and frontend is still allowed. Policies enforce rather than log, and being in the same namespace grants nothing once a policy applies.'),
  mc('t590-a3', 'cluster-dns', 'After a default-deny egress policy is applied, every service fails with “could not resolve host”. What is the fix?',
   [('a', 'Allow egress to the cluster DNS pods on port 53 over UDP and TCP'),
    ('b', 'Switch the services to call each other by pod IP addresses'),
    ('c', 'Add an ingress policy that allows traffic into the DNS pods'),
    ('d', 'Restart the DNS pods so they pick up the new policy')], 'a',
   'The pods’ own egress to DNS is blocked, so an egress allow to the DNS pods on port 53 restores resolution. Pod IPs change, so hard-coding them breaks on the next reschedule; DNS pods accept traffic already, and restarting them does not change the client-side block.'),
  mc('t590-a4', 'ingress-gateway', 'Twenty HTTP services each need a public hostname with TLS. Which setup keeps cost and operations down?',
   [('a', 'One Service of type LoadBalancer for each of the twenty services'),
    ('b', 'A NodePort per service, with each node’s IP in public DNS records'),
    ('c', 'One shared Gateway or Ingress routing by hostname to each Service'),
    ('d', 'A ClusterIP per service with traffic sent straight to pod addresses')], 'c',
   'One shared layer 7 entry point handles TLS and routes by hostname, so you run one load balancer instead of twenty. Twenty LoadBalancer Services cost twenty load balancers, public node IPs break when nodes change, and ClusterIPs and pod addresses are not reachable from outside.'),
  est('t590-a5', 'service-virtual-ip', 'Four client pods each hold one long-lived HTTP/2 connection to a ClusterIP Service with 10 ready server pods. At most how many server pods receive traffic?', 'pods', 4,
   ['Each client opens one connection and reuses it for every request', 'Connections are never closed during the period'], 'One pod per connection, 4 connections', '4 connections reach at most 4 pods',
   'Design implication: 6 of the 10 pods sit idle while 4 run hot, so balance per request with a client library or proxy, or cap connection lifetime so connections spread again.', 0.05, [10, 1]),
  order('t590-a6', 'ingress-gateway', 'Order the hops a browser request takes to reach a pod behind a Gateway.',
   ['DNS resolves the hostname to the cloud load balancer', 'The load balancer forwards to the gateway pods', 'The gateway terminates TLS and matches a route', 'The route sends it to a backend Service', 'The Service forwards the connection to a ready pod'],
   ['s3', 's5', 's1', 's4', 's2'], 'Name, edge load balancer, layer 7 routing, Service, pod: each hop narrows where the request goes.')],
 flash(590, [('Service balancing unit?', 'Connections, not requests; long-lived HTTP/2 connections can pin traffic to a few pods.'),
             ('Ingress vs Gateway API?', 'Both give one shared layer 7 entry; the Gateway API is the successor, with roles split between platform and app teams.'),
             ('First rule after default-deny egress?', 'Allow DNS: egress to the cluster DNS pods on port 53, UDP and TCP.')]),
 src([('Kubernetes: Service', 'https://kubernetes.io/docs/concepts/services-networking/service/'),
      ('Kubernetes: Gateway API', 'https://kubernetes.io/docs/concepts/services-networking/gateway/'),
      ('Kubernetes: Network Policies', 'https://kubernetes.io/docs/concepts/services-networking/network-policies/'),
      ('Kubernetes: DNS for Services and Pods', 'https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/')]),
 deep(['service-virtual-ip', 'ingress-gateway', 'network-policy', 'cluster-dns'], 'How traffic finds pods inside and into a cluster',
  ['Every pod gets its own IP address on a flat cluster network, and any pod can reach any other without NAT. The network plugin implements this, using routes, overlays or the cloud’s own network, depending on the plugin. Pod addresses change whenever pods are rescheduled, so nothing should depend on them.',
   'A Service selects pods by label. The control plane keeps EndpointSlices listing the ready pods, and each node programs forwarding rules, through kube-proxy or an eBPF-based plugin, so that a connection to the Service’s virtual IP is sent to one endpoint. The choice is made once per connection. Cluster DNS gives each Service a name of the form service.namespace.svc.cluster.local, and pods usually use the short name within their namespace.',
   'Outside traffic needs an entry point. A Service of type LoadBalancer provisions a cloud load balancer per Service and suits a few TCP services. For many HTTP services, an Ingress or a Gateway gives one shared layer 7 entry: a controller runs proxy pods behind one load balancer, terminates TLS and routes by hostname and path to Services. The Ingress API is stable but no longer gaining features; the Gateway API is its successor, with GatewayClass, Gateway and route resources owned by different roles.',
   'Network policies are allow lists. A pod no policy selects accepts and sends anything. When a policy selects it for ingress or egress, only traffic that some policy allows in that direction passes, and policies add up rather than override each other. Rules match pods by label, namespaces by label, or IP blocks, plus ports. Enforcement is done by the network plugin, so a cluster whose plugin lacks policy support accepts policies and silently ignores them.',
   'A practical rollout is default-deny per namespace for ingress, then explicit allows between tiers, then egress control for sensitive workloads. Egress policies must allow DNS first, then the specific destinations each workload needs, such as the database and a payment API’s address range. Test policies in staging with real traffic, because a missing rule shows up as timeouts or resolution failures, not a clear error.'],
  ['Clusters with many HTTP services that need hostnames, TLS and routing in one place.', 'Multi-team or regulated clusters where lateral movement between pods must be limited.'],
  ['Avoid a LoadBalancer Service per HTTP service when one shared gateway would do.', 'Avoid relying on network policies before confirming the network plugin enforces them.'],
  ['Option', 'Good for', 'Cost'],
  [['ClusterIP Service', 'Calls inside the cluster', 'Balances per connection only'],
   ['LoadBalancer Service', 'A few TCP or UDP services', 'One cloud load balancer each'],
   ['Ingress or Gateway', 'Many HTTP services, TLS, routing', 'A controller to run and upgrade'],
   ['Network policy', 'Limiting pod-to-pod traffic', 'Rules to maintain, needs plugin support']],
  'Connection pinning on a Service',
  ['10 server pods behind a ClusterIP Service', '4 client pods, each with one long-lived HTTP/2 connection', 'Each client sends 500 requests per second, illustrative'],
  ['Total load: 4 × 500 = 2,000 requests per second.',
   'With per-connection balancing, at most 4 pods serve it: 2,000 ÷ 4 = 500 requests per second each.',
   'With per-request balancing over 10 pods: 2,000 ÷ 10 = 200 requests per second each.'],
  'The same traffic is 2.5 times hotter per pod when long-lived connections pin it, which is why gRPC services balance per request in the client or a proxy.',
  'Services, gateways and policies in the docs', 'Official documentation',
  'The Kubernetes documentation describes Services as a stable virtual IP and DNS name backed by EndpointSlices of ready pods, and notes that the Ingress API is frozen while the Gateway API is the recommended successor for new features. Its network policy page states that pods are non-isolated by default, that policies are additive, and that a network plugin which supports NetworkPolicy is required for them to have any effect.',
  [('“The Service load-balances, so every pod gets equal traffic.”', '“I’d check for long-lived connections; a Service balances per connection, not per request.”'),
   ('“We applied default-deny; the cluster is locked down.”', '“I’d confirm the network plugin enforces policies and that DNS egress is still allowed.”')],
  ['A Service gives ready pods a stable name and virtual IP, balanced per connection.', 'Use one shared Gateway or Ingress for many HTTP services, not a load balancer each.', 'Network policies are additive allow lists; selected pods drop everything else.', 'Allow DNS egress first, and confirm the plugin enforces policies.']),
 predict('The gRPC service with idle pods',
  'A gRPC service is scaled from 4 to 12 pods during a traffic spike. Its 3 client pods each hold one long-lived connection through a ClusterIP Service. Latency does not improve.',
  [('a', 'The 3 existing connections still pin all traffic to at most 3 pods',
    'Right: new pods only get connections opened after they are ready, and these clients never reconnect.'),
   ('b', 'The new pods are failing readiness, so the Service ignores them',
    'Possible in general, but the connection pattern alone explains it here.'),
   ('c', 'The Service needs a restart to notice the new endpoints',
    'Endpoints update on their own; the existing connections are what does not move.')], 'a',
  'Balance per request in the gRPC client over the endpoint list, or set a maximum connection age so clients reconnect and spread across new pods.'),
 see([(52, 'Service discovery in general, of which cluster DNS is one form'), (12, 'Layer 4 vs layer 7 balancing, the difference behind connection pinning'), (588, 'A mesh that balances per request and adds mTLS between pods')])))

# ---------------------------------------------------------------- 681 cluster upgrades
T.append(topic(681, 'cluster-upgrades-node-drains', R, 16, 'Cluster Upgrades: Version Skew, Drains and Disruption Budgets',
 ['Plan a cluster upgrade in the right order, within the supported version skew',
  'Explain how a node drain evicts pods and how disruption budgets slow or block it',
  'Choose between surge upgrades and a new node pool, and estimate how long an upgrade takes'],
 3, 13, [322, 589],
 [text(681, 1, 'Why upgrades never stop',
   'Kubernetes ships a minor release roughly three times a year, and each one gets about a year of patch support upstream; managed services publish their own, similar support windows. A cluster left alone falls out of support within about a year and then has to jump several versions under pressure. Teams that upgrade every release, one minor version at a time, keep each step small and practised.',
   ['version-skew']),
  text(681, 2, 'Order and skew: control plane first',
   'Upgrade the control plane first, then the nodes. The kubelet on a node may be older than the API server, up to three minor versions behind on recent releases, but never newer, so nodes can lag while you roll them. Before starting, check the release notes for APIs removed in the target version: manifests, charts and controllers that still use a removed API version fail to apply after the upgrade, even though the cluster itself looks healthy.',
   ['version-skew']),
  diagram(681, 3, 'Draining one node', 'Every eviction asks the disruption budget first.', ['node-drain', 'disruption-budget'],
   ['Cordon the node so no new pods are scheduled on it',
    'Request an eviction for each pod on the node',
    'The API server checks the pod’s disruption budget',
    'Allowed: the pod gets SIGTERM and its grace period, and its controller recreates it elsewhere',
    'Refused: the drain waits and retries until the budget allows it',
    'When the node is empty, upgrade or replace it']),
  text(681, 4, 'Worked example: a 30-node surge upgrade',
   'A node pool of 30 nodes is upgraded with a surge of 3: three new nodes are added, three old nodes are drained and removed, and so on. If each batch takes about 10 minutes to boot, drain and delete, the pool needs 30 ÷ 3 = 10 batches, and 10 × 10 = 100 minutes. Raising the surge to 6 roughly halves the time but needs quota for 6 extra nodes and doubles how many pods move at once.',
   ['upgrade-strategy']),
  text(681, 5, 'Trap: a budget that never lets anything go',
   'A service runs 2 replicas with a disruption budget of minAvailable 2, or maxUnavailable 0. Every eviction is refused, so every drain stalls on that node. Managed services wait for a while and then fail the upgrade or force the eviction, depending on the provider. Size budgets so one pod can always go: for example 3 replicas with maxUnavailable 1, spread across zones.',
   ['disruption-budget'])],
 [mc('t681-a1', 'version-skew', 'A cluster runs 1.35 on the control plane and the nodes. You are moving to 1.36. Which order is supported?',
   [('a', 'Upgrade the nodes to 1.36 first, then the control plane'),
    ('b', 'Upgrade the control plane to 1.36, then roll the nodes'),
    ('c', 'Upgrade both at once so that they never differ'),
    ('d', 'Jump the nodes straight to 1.37 while the control plane is upgraded')], 'b',
   'Kubelets may lag the API server but must not be newer, so the control plane goes first. Nodes first or nodes at 1.37 would make kubelets newer than the API server, and upgrading everything at once removes the chance to stop if the control plane step goes wrong.'),
  mc('t681-a2', 'disruption-budget', 'A drain hangs on one node. The service there has 2 replicas and a disruption budget of minAvailable 2. Why?',
   [('a', 'The node’s kubelet is too old to accept eviction requests'),
    ('b', 'The pods are ignoring SIGTERM, so their grace period never ends'),
    ('c', 'Any eviction would drop below 2 available, so each is refused'),
    ('d', 'Drains only evict pods that have no disruption budget at all')], 'c',
   'With minAvailable equal to the replica count, no voluntary eviction is ever allowed, so the drain retries forever. Kubelet version does not affect evictions, a pod ignoring SIGTERM is killed after its grace period, and drains do evict pods with budgets, as long as the budget allows it.'),
  mc('t681-a3', 'version-skew', 'The cluster upgrade succeeds, but the next deploy fails with “no matches for kind” on an API version. What happened?',
   [('a', 'The deploy used an API version that the new release removed'),
    ('b', 'The new nodes have not pulled the container images yet'),
    ('c', 'The scheduler is still running the previous minor version'),
    ('d', 'The disruption budget blocked the deploy during the upgrade')], 'a',
   'Removed API versions are the classic upgrade break: the cluster is fine but old manifests no longer match any kind. Image pulls fail later and differently, the control plane was upgraded as a whole, and disruption budgets limit evictions, not deploys.'),
  mc('t681-a4', 'upgrade-strategy', 'For a critical cluster you want to be able to undo a node upgrade within minutes. Which approach gives that?',
   [('a', 'An in-place upgrade of each existing node, one node at a time'),
    ('b', 'A surge upgrade with a large surge so it finishes sooner'),
    ('c', 'Pausing the cluster autoscaler for the whole surge upgrade'),
    ('d', 'A new node pool on the new version, keeping the old pool')], 'd',
   'With a new pool beside the old one, undoing means moving pods back to nodes that still exist. In-place and surge upgrades replace the old nodes as they go, so a rollback is another full upgrade, and pausing the autoscaler changes nothing about reversibility.'),
  est('t681-a5', 'upgrade-strategy', 'A node pool of 30 nodes is upgraded 3 nodes at a time. Each batch takes about 10 minutes to add, drain and remove. How long does the pool take?', 'minutes', 100,
   ['Batches run one after another', 'No drain is blocked by a disruption budget'], '(30 ÷ 3) × 10 minutes', '10 batches × 10 minutes = 100 minutes',
   'Sanity check: one batch alone is 10 minutes, and one node at a time would be 300; a blocked drain adds its full wait to whichever batch it hits.', 0.05, [10, 300]),
  order('t681-a6', 'version-skew', 'Order a minor-version cluster upgrade.',
   ['Check release notes and fix uses of removed APIs', 'Upgrade the control plane', 'Upgrade cluster add-ons that must match the version', 'Roll each node pool, draining nodes within their budgets', 'Verify workloads and remove the old nodes'],
   ['s2', 's4', 's1', 's5', 's3'], 'Fix removed APIs before anything moves, then control plane, add-ons, nodes, and verification.')],
 flash(681, [('Upgrade order?', 'Control plane first, then nodes; kubelets may lag the API server but must not be newer.'),
             ('What does a drain do?', 'Cordons the node, then evicts each pod through the eviction API, which checks disruption budgets.'),
             ('A budget that blocks every drain?', 'minAvailable equal to replicas, or maxUnavailable 0; leave room for one pod to go.')]),
 src([('Kubernetes: Version Skew Policy', 'https://kubernetes.io/releases/version-skew-policy/'),
      ('Kubernetes: Safely Drain a Node', 'https://kubernetes.io/docs/tasks/administer-cluster/safely-drain-node/'),
      ('Kubernetes: Specifying a Disruption Budget', 'https://kubernetes.io/docs/tasks/run-application/configure-pdb/'),
      ('Google Cloud: Node pool upgrade strategies', 'https://cloud.google.com/kubernetes-engine/docs/concepts/node-pool-upgrade-strategies')]),
 deep(['version-skew', 'node-drain', 'disruption-budget', 'upgrade-strategy'], 'How a cluster is upgraded without an outage',
  ['Prepare first. Read the release notes for the target minor version, list removed and deprecated APIs, and scan manifests, charts and the live cluster for them. Check that add-ons such as the network plugin, DNS, ingress controller and storage drivers support the new version. Upgrade a staging cluster first and run the same checks there, because removed APIs are the most common cause of a successful upgrade followed by failed deploys.',
   'Upgrade the control plane next. On a managed service this is one operation; the provider replaces the API servers and controllers while the API stays reachable. The version skew policy then lets nodes stay behind: a kubelet may be older than the API server, by up to three minor versions on current releases, but never newer. That gap is what allows nodes to be rolled gradually after the control plane is done.',
   'Each node is replaced by draining it. A drain cordons the node so nothing new lands there, then evicts every pod through the eviction API. Each eviction is checked against the pod’s disruption budget, which states how many replicas must stay available or may be unavailable. Allowed evictions terminate the pod with its normal grace period, and its controller recreates it on another node; refused evictions are retried until enough replicas are ready elsewhere.',
   'Surge upgrades add a few new nodes, drain the same number of old ones, and repeat; maxSurge and maxUnavailable trade speed against extra capacity and disruption. A blue-green node pool creates a full pool on the new version, moves workloads by cordoning and draining the old pool, and keeps the old nodes for a soak period, which makes undoing quick at the cost of running two pools for a while.',
   'Disruption budgets must allow progress. A budget that permits zero disruptions blocks every drain; managed services wait for a provider-specific time, then fail the upgrade or force the eviction. Good budgets leave room for one replica to go, and pair with enough replicas spread across zones and readiness probes that only pass when a pod can really serve. Single-replica workloads cannot be both protected and drained, so they need a maintenance window or a second replica.'],
  ['Every cluster, every minor release: small regular upgrades instead of rare forced jumps.', 'Production services with disruption budgets that leave room for one replica to move.'],
  ['Avoid skipping minor versions on the control plane; upgrade one minor at a time.', 'Avoid budgets of zero allowed disruptions, and in-place upgrades where a fast undo matters.'],
  ['Strategy', 'Speed', 'Undo', 'Extra capacity'],
  [['Surge, small batches', 'Slow', 'Another upgrade', 'A few nodes'],
   ['Surge, large batches', 'Fast', 'Another upgrade', 'Quota for the surge'],
   ['Blue-green node pool', 'Medium', 'Move pods back to the old pool', 'A whole second pool for a while']],
  'How long a node pool upgrade takes',
  ['30 nodes, surge of 3', 'About 10 minutes per batch to boot, drain and delete', 'One blocked drain waits 60 minutes before the provider forces it, illustrative'],
  ['Batches: 30 ÷ 3 = 10.',
   'Normal time: 10 × 10 = 100 minutes.',
   'One blocked drain adds its 60-minute wait to one batch: about 160 minutes in total.'],
  'Surge size sets the pace, but a single badly sized disruption budget can add more time than the rest of the upgrade combined.',
  'Upgrade rules in the Kubernetes docs', 'Official documentation',
  'The Kubernetes version skew policy says the kubelet must not be newer than the API server and may be up to three minor versions older, and that the control plane is upgraded before nodes. The safe-drain task describes cordoning and evicting through the eviction API, which respects disruption budgets. Google Cloud documents surge and blue-green node pool upgrade strategies for managed clusters.',
  [('“We will upgrade the cluster when we have to.”', '“I’d upgrade every minor release, one version at a time, so each step is small and practised.”'),
   ('“Set the budget to zero disruptions so the service is always safe.”', '“I’d allow one pod to go and run enough replicas; a zero budget blocks every drain.”')],
  ['Upgrade the control plane first; kubelets may lag but never lead.', 'Find and fix removed APIs before the upgrade, not after.', 'Drains evict through disruption budgets; size budgets so one pod can always move.', 'Surge for speed; a new node pool when a fast undo matters.']),
 predict('The upgrade that stopped at node 7',
  'A surge upgrade of a 20-node pool has been stuck on node 7 for 40 minutes. Node 7 runs one pod of a cache with 1 replica and a disruption budget of minAvailable 1.',
  [('a', 'The eviction is refused, because removing the only replica would break minAvailable 1',
    'Right: with one replica and minAvailable 1, no voluntary eviction is ever allowed.'),
   ('b', 'Node 7 is broken and cannot be drained until it is rebooted',
    'The node is fine; the API server is refusing the eviction.'),
   ('c', 'The surge quota ran out, so no new node can be added',
    'The new nodes already exist; the stall is on emptying the old one.')], 'a',
  'Give the cache a second replica in another zone and set maxUnavailable 1, or schedule a window to drain it deliberately; the provider may otherwise force the eviction after its timeout.'),
 see([(322, 'Pods, probes and disruption budgets introduced'), (589, 'Spread rules decide where drained pods land'), (324, 'The same safety ideas as a canary, applied to nodes instead of code')])))
